1	package agentusage
2	
3	import (
4		"cmp"
5		"slices"
6	)
7	
8	// pos orders lines the way ParseSession reads them (D3).
9	type pos struct {
10		rank string // "0" parent; "1"+agentID+"\x00"+baseName for a sub-agent
11		off  int64
12	}
13	
14	// parentRank is the rank of the parent transcript; it sorts before every
15	// sub-agent rank.
16	const parentRank = "0"
17	
18	// subAgentRank is the rank of a sub-agent's transcript: sub-agents are read by
19	// ID, then by base name.
20	func subAgentRank(agentID, name string) string { return "1" + agentID + "\x00" + name }
21	
22	// transcriptRank is subAgentRank made unique per transcript: the raw ID and
23	// the path break ties between sub-agents whose sanitized IDs and base names
24	// coincide. It is a function of the transcript alone, so it is stable from one
25	// pass to the next, and it doubles as the agent's key in a table.
26	func transcriptRank(agentID, name, rawID, path string) string {
27		return subAgentRank(agentID, name) + "\x00" + rawID + "\x00" + path
28	}
29	
30	// compare orders positions by rank, then by offset.
31	func (p pos) compare(o pos) int {
32		if c := cmp.Compare(p.rank, o.rank); c != 0 {
33			return c
34		}
35		return cmp.Compare(p.off, o.off)
36	}
37	
38	// msgKey identifies one message of a session. A message with an id is keyed
39	// by the id alone; one without is keyed by where it was read (file rank and
40	// offset).
41	type msgKey struct {
42		id   string
43		file string
44		off  int64
45	}
46	
47	// entry is the last state seen of one message. Which line is "last" is a
48	// function of positions, never of arrival.
49	type entry struct {
50		first, last pos
51		agent       string // agent ID of the last line; "" for the parent
52		file        string // base name of one file the message was seen in
53		otherFiles  []string
54		model       string
55		tokens      Tokens
56		stopNull    bool
57	}
58	
59	// addFile remembers that the message was also seen in the file named name.
60	func (e *entry) addFile(name string) {
61		if e.file == name || slices.Contains(e.otherFiles, name) {
62			return
63		}
64		e.otherFiles = append(e.otherFiles, name)
65	}
66	
67	// absorb folds o into e: the greatest position gives the state, the smallest
68	// gives first, and the files are united.
69	func (e *entry) absorb(o *entry) {
70		if o.last.compare(e.last) >= 0 {
71			e.last, e.agent, e.model, e.tokens, e.stopNull = o.last, o.agent, o.model, o.tokens, o.stopNull
72		}
73		if o.first.compare(e.first) < 0 {
74			e.first = o.first
75		}
76		e.addFile(o.file)
77		for _, f := range o.otherFiles {
78			e.addFile(f)
79		}
80	}
81	
82	// spill totals the lines that no longer get a table entry.
83	type spill struct {
84		tokens   Tokens
85		messages int
86		partial  int
87		models   modelSet
88	}
89	
90	// issueAt is a FileIssue with the position of the line it describes.
91	type issueAt struct {
92		p  pos
93		fi FileIssue
94	}
95	
96	// compare orders issues by position, then kind, then file.
97	func (a issueAt) compare(b issueAt) int {
98		if c := a.p.compare(b.p); c != 0 {
99			return c
100		}
101		if c := cmp.Compare(a.fi.Kind, b.fi.Kind); c != 0 {
102			return c
103		}
104		return cmp.Compare(a.fi.File, b.fi.File)
105	}
106	
107	// table folds lines into per-key last states, ordered by position (D3). It
108	// is both the content of a Delta and the state of an Aggregate. Two declared
109	// exceptions to order-freedom: which no-id lines spill past maxNoIDEntries,
110	// and which models fill a spill's maxModelsPerAgent, follow arrival order.
111	type table struct {
112		entries map[msgKey]*entry
113		noID    int // entries holding a line without message id
114		spill   map[string]*spill
115		// counters of lines; CrossFileDuplicates is derived by finish.
116		unreadable, noUsage, noMessageID, oversized int
117		// capped holds the unreadable/oversized issues per file name, trimmed to
118		// the maxFileIssuesPerFile smallest positions; stateIssues holds the
119		// other kinds, which occur once per file.
120		capped      map[string][]issueAt
121		stateIssues []issueAt
122		// versions maps a distinct client version to its first position, at most
123		// maxVersions of them (the smallest positions).
124		versions map[string]pos
125	}
126	
127	func newTable() *table {
128		return &table{
129			entries:  map[msgKey]*entry{},
130			spill:    map[string]*spill{},
131			capped:   map[string][]issueAt{},
132			versions: map[string]pos{},
133		}
134	}
135	
136	// addLine decodes one line of the file named name for agent ("" for the
137	// parent) and folds it. Synthetic and ignored lines never count.
138	func (t *table) addLine(agent, name string, p pos, line []byte) {
139		r, kind := decodeLine(line)
140		if kind != kindUnreadable {
141			t.noteVersion(r.Version, p)
142		}
143		switch kind {
144		case kindUsage:
145			t.addUsage(agent, name, p, r)
146		case kindNoUsage:
147			t.noUsage++
148		case kindUnreadable:
149			t.unreadable++
150			t.addFileIssue(name, p, IssueUnreadable)
151		case kindIgnored, kindSynthetic:
152		}
153	}
154	
155	// addOversized counts a line longer than MaxLineBytes that started at p.
156	func (t *table) addOversized(name string, p pos) {
157		t.oversized++
158		t.addFileIssue(name, p, IssueOversized)
159	}
160	
161	// addUsage folds one usage record in.
162	func (t *table) addUsage(agent, name string, p pos, r record) {
163		key := msgKey{id: r.MessageID}
164		if r.MessageID == "" {
165			key = msgKey{file: p.rank, off: p.off}
166			t.noMessageID++
167			if _, ok := t.entries[key]; !ok {
168				if t.noID >= maxNoIDEntries {
169					t.addSpill(agent, r)
170					return
171				}
172				t.noID++
173			}
174		}
175		t.put(key, &entry{
176			first: p, last: p, agent: agent, file: name,
177			model: r.Model, tokens: r.Usage, stopNull: r.StopNull,
178		})
179	}
180	
181	// put folds e into the table under key; the table keeps its own copy.
182	func (t *table) put(key msgKey, e *entry) {
183		if cur, ok := t.entries[key]; ok {
184			cur.absorb(e)
185			return
186		}
187		c := *e
188		c.otherFiles = slices.Clone(e.otherFiles)
189		t.entries[key] = &c
190	}
191	
192	// addSpill counts a no-id line that gets no table entry.
193	func (t *table) addSpill(agent string, r record) {
194		sp := t.spill[agent]
195		if sp == nil {
196			sp = &spill{}
197			t.spill[agent] = sp
198		}
199		sp.absorbRecord(r)
200	}
201	
202	func (s *spill) absorbRecord(r record) {
203		s.tokens = s.tokens.Add(r.Usage)
204		s.messages++
205		if r.StopNull {
206			s.partial++
207		}
208		s.models.add(r.Model)
209	}
210	
211	// noteVersion records a client version with its first position, keeping the
212	// maxVersions smallest.
213	func (t *table) noteVersion(v string, p pos) {
214		v = sanitizeLabel(v)
215		if v == "" {
216			return
217		}
218		if cur, ok := t.versions[v]; ok {
219			if p.compare(cur) < 0 {
220				t.versions[v] = p
221			}
222			return
223		}
224		if len(t.versions) >= maxVersions {
225			worst, wp := "", pos{}
226			for k, kp := range t.versions {
227				if worst == "" || kp.compare(wp) > 0 {
228					worst, wp = k, kp
229				}
230			}
231			if p.compare(wp) >= 0 {
232				return
233			}
234			delete(t.versions, worst)
235		}
236		t.versions[v] = p
237	}
238	
239	// addFileIssue records an issue of the file named name. Unreadable and
240	// oversized ones are kept at most maxFileIssuesPerFile per file (the counters
241	// are not capped); the other kinds occur once per file and are always kept.
242	func (t *table) addFileIssue(name string, p pos, kind IssueKind) {
243		it := issueAt{p: p, fi: FileIssue{File: name, Offset: p.off, Kind: kind}}
244		if kind != IssueUnreadable && kind != IssueOversized {
245			t.stateIssues = append(t.stateIssues, it)
246			return
247		}
248		t.capped[name] = trimIssues(append(t.capped[name], it), 2*maxFileIssuesPerFile)
249	}
250	
251	// trimIssues keeps the maxFileIssuesPerFile smallest issues once s has grown
252	// to limit entries.
253	func trimIssues(s []issueAt, limit int) []issueAt {
254		if len(s) < limit {
255			return s
256		}
257		slices.SortFunc(s, issueAt.compare)
258		return s[:min(len(s), maxFileIssuesPerFile)]
259	}
260	
261	// merge folds o into t as if o's lines had been added to t. o is not modified
262	// and shares nothing with t afterwards.
263	func (t *table) merge(o *table) {
264		for k, e := range o.entries {
265			_, had := t.entries[k]
266			t.put(k, e)
267			if !had && k.id == "" {
268				t.noID++
269			}
270		}
271		for agent, sp := range o.spill {
272			dst := t.spill[agent]
273			if dst == nil {
274				dst = &spill{}
275				t.spill[agent] = dst
276			}
277			dst.tokens = dst.tokens.Add(sp.tokens)
278			dst.messages += sp.messages
279			dst.partial += sp.partial
280			for _, m := range sp.models.list {
281				dst.models.add(m)
282			}
283		}
284		t.unreadable += o.unreadable
285		t.noUsage += o.noUsage
286		t.noMessageID += o.noMessageID
287		t.oversized += o.oversized
288		for name, s := range o.capped {
289			t.capped[name] = trimIssues(append(t.capped[name], s...), 2*maxFileIssuesPerFile)
290		}
291		t.stateIssues = append(t.stateIssues, o.stateIssues...)
292		for v, p := range o.versions {
293			t.noteVersion(v, p)
294		}
295	}
296	
297	// orderedKeys returns the entry keys by first position: the order messages
298	// first appear in a sequential read.
299	func (t *table) orderedKeys() []msgKey {
300		keys := make([]msgKey, 0, len(t.entries))
301		for k := range t.entries {
302			keys = append(keys, k)
303		}
304		slices.SortFunc(keys, func(a, b msgKey) int {
305			if c := t.entries[a].first.compare(t.entries[b].first); c != 0 {
306				return c
307			}
308			return cmp.Or(cmp.Compare(a.id, b.id), cmp.Compare(a.file, b.file), cmp.Compare(a.off, b.off))
309		})
310		return keys
311	}
312	
313	// finish computes the counters of the agents given (identity fields set, the
314	// parent flagged Main), the line diagnostics and the versions, all deep
315	// copies. Agents are matched by key (ID when unset); the Main agent matches
316	// the parent's "".
317	func (t *table) finish(agents []Agent) ([]Agent, Diagnostics, []string) {
318		out := slices.Clone(agents)
319		idx := make(map[string]int, len(out))
320		for i := range out {
321			out[i].Tokens, out[i].Models = Tokens{}, nil
322			out[i].Messages, out[i].PartialMessages = 0, 0
323			id := cmp.Or(out[i].key, out[i].ID)
324			if out[i].Main {
325				id = ""
326			}
327			out[i].key = ""
328			idx[id] = i
329		}
330		models := make([]modelSet, len(out))
331		cross := 0
332		for _, k := range t.orderedKeys() {
333			e := t.entries[k]
334			cross += len(e.otherFiles)
335			if i, ok := idx[e.agent]; ok {
336				addEntry(&out[i], &models[i], e)
337			}
338		}
339		for agent, sp := range t.spill {
340			if i, ok := idx[agent]; ok {
341				addSpill(&out[i], &models[i], sp)
342			}
343		}
344		for i := range out {
345			out[i].Models = models[i].list
346		}
347		return out, t.diagnostics(cross), t.orderedVersions()
348	}
349	
350	// addEntry adds one message's final state to its agent.
351	func addEntry(ag *Agent, ms *modelSet, e *entry) {
352		ag.Tokens = ag.Tokens.Add(e.tokens)
353		ag.Messages++
354		if e.stopNull {
355			ag.PartialMessages++
356		}
357		ms.add(e.model)
358	}
359	
360	// addSpill adds a spill's totals to its agent.
361	func addSpill(ag *Agent, ms *modelSet, sp *spill) {
362		ag.Tokens = ag.Tokens.Add(sp.tokens)
363		ag.Messages += sp.messages
364		ag.PartialMessages += sp.partial
365		for _, m := range sp.models.list {
366			ms.add(m)
367		}
368	}
369	
370	// diagnostics builds the line diagnostics; cross is the number of cross-file
371	// duplicates found by finish.
372	func (t *table) diagnostics(cross int) Diagnostics {
373		d := Diagnostics{
374			UnreadableLines: t.unreadable, OversizedLines: t.oversized,
375			NoUsage: t.noUsage, NoMessageID: t.noMessageID, CrossFileDuplicates: cross,
376		}
377		all := slices.Clone(t.stateIssues)
378		for _, s := range t.capped {
379			sorted := slices.Clone(s)
380			slices.SortFunc(sorted, issueAt.compare)
381			all = append(all, sorted[:min(len(sorted), maxFileIssuesPerFile)]...)
382		}
383		slices.SortFunc(all, issueAt.compare)
384		for _, it := range all {
385			d.Files = append(d.Files, it.fi)
386		}
387		return d
388	}
389	
390	// orderedVersions returns the versions by first position.
391	func (t *table) orderedVersions() []string {
392		var vs []string
393		for v := range t.versions {
394			vs = append(vs, v)
395		}
396		slices.SortFunc(vs, func(a, b string) int { return t.versions[a].compare(t.versions[b]) })
397		return vs
398	}
399

