25	// probe counts how a test's transcripts are opened and read.
26	type probe struct {
27		opens int
28		bytes int64
29	}
30	
31	// countingFile counts the bytes read through Read and ReadAt.
32	type countingFile struct {
33		transcriptFile
34		p *probe
35	}
