176	func offOf(t *testing.T, part *table, id string) int64 {
177		t.Helper()
178		if part == nil || part.entries[msgKey{id: id}] == nil {
179			t.Fatalf("message %q not in the part (ids %v)", id, partIDs(part))
180		}
181		return part.entries[msgKey{id: id}].last.off
182	}
