518			t.Run(tc.name, func(t *testing.T) {
519				path := filepath.Join(t.TempDir(), "p.jsonl")
520				putFile(t, path, initial)
521				fr1 := step(t, cur(path))
522				if fr1.next.id == nil || fr1.next.offset != int64(len(initial)) {
523					t.Fatalf("setup: id nil=%v offset=%d", fr1.next.id == nil, fr1.next.offset)
524				}
525				tc.mutate(t, path)
526				if fr2 := pass(fr1.next); !fr2.reset {
527					t.Errorf("reset = false, want true (part %v)", partIDs(fr2.part))
528				}
529			})
530		}
531	}
532	
533	// Nothing was read yet: a missing or unusable path is a state, not a reset.
534	func TestReadFileFreshCursorOnAnUnusablePath(t *testing.T) {
535		isolateReadFileHome(t)
536		tests := []struct {
537			name  string
538			setup func(t *testing.T, dir string) string
539		}{
540			{"missing", func(t *testing.T, dir string) string { return filepath.Join(dir, "p.jsonl") }},
541			{"directory", func(t *testing.T, dir string) string {
542				p := filepath.Join(dir, "p.jsonl")
543				if err := os.Mkdir(p, 0o700); err != nil {
544					t.Fatal(err)
545				}
546				return p
547			}},
548			{"symbolic link to a real transcript", func(t *testing.T, dir string) string {
549				target := filepath.Join(dir, "real.jsonl")
550				putFile(t, target, ln("a"))
551				p := filepath.Join(dir, "p.jsonl")
552				if err := os.Symlink(target, p); err != nil {
553					t.Skipf("symlinks unavailable: %v", err)
554				}
555				return p
556			}},
557		}
558		for _, tc := range tests {
559			t.Run(tc.name, func(t *testing.T) {
560				path := tc.setup(t, t.TempDir())
561				fr := pass(cur(path))
562				if fr.reset {
563					t.Fatal("reset = true, want a state issue")
564				}
565				if !fr.next.hasIssue || fr.next.issue != IssueOpenFailed {
566					t.Errorf("issue = %v (has %v), want IssueOpenFailed", fr.next.issue, fr.next.hasIssue)
567				}
568				if fr.part != nil && len(fr.part.entries) > 0 {
569					t.Errorf("read something from an unusable path: %v", partIDs(fr.part))
570				}
571				if fr.next.offset != 0 || fr.next.id != nil {
572					t.Errorf("cursor moved: offset=%d id nil=%v", fr.next.offset, fr.next.id == nil)
573				}
574			})
575		}
576	}
577	
578	// --- D6: errors are states, cleared by a later success --------------------
579	
580	func TestReadFileOpenFailureClearsOnALaterSuccess(t *testing.T) {
581		isolateReadFileHome(t)
582		path := filepath.Join(t.TempDir(), "p.jsonl")
583		fr1 := step(t, cur(path))
584		if !fr1.next.hasIssue || fr1.next.issue != IssueOpenFailed {
585			t.Fatalf("missing file: issue = %v (has %v)", fr1.next.issue, fr1.next.hasIssue)
586		}
587		putFile(t, path, cat(ln("a"), ln("b")))
588		fr2 := step(t, fr1.next)
589		if fr2.next.hasIssue {
590			t.Errorf("issue %v still set after a successful read", fr2.next.issue)
591		}
592		if got := partIDs(fr2.part); !reflect.DeepEqual(got, []string{"a", "b"}) {
593			t.Errorf("ids = %v, want [a b]", got)
594		}
595	}
596	
597	func TestReadFileOpenErrorOnAFreshCursorIsAStateThenClears(t *testing.T) {
598		isolateReadFileHome(t)
599		path := filepath.Join(t.TempDir(), "p.jsonl")
600		putFile(t, path, ln("a"))
601		orig := openTranscript
602		swapOpen(t, func(string) (transcriptFile, error) { return nil, os.ErrPermission })
603	
604		fr1 := pass(cur(path))
605		if fr1.reset || !fr1.next.hasIssue || fr1.next.issue != IssueOpenFailed {
606			t.Fatalf("reset=%v issue=%v (has %v), want a state IssueOpenFailed", fr1.reset, fr1.next.issue, fr1.next.hasIssue)
607		}
608		openTranscript = orig
609		fr2 := step(t, fr1.next)
610		if fr2.next.hasIssue || !reflect.DeepEqual(partIDs(fr2.part), []string{"a"}) {
611			t.Errorf("after recovery: issue=%v ids=%v", fr2.next.hasIssue, partIDs(fr2.part))
612		}
613	}
614	
615	// A read error keeps the lines before it and is a state; the bytes between
616	// Consumed and End must be read again even when End is the file's size.
617	func TestReadFileReadErrorIsAStateAndBytesAreReadAgain(t *testing.T) {
618		isolateReadFileHome(t)
619		l := int64(len(ln("a")))
620		tests := []struct {
621			name     string
622			content  []byte
623			limit    int64
624			consumed int64
625			first    []string
626			second   []string
627			tail     bool
628		}{
629			{
630				name:     "error after the whole file, on a held-back tail",
631				content:  cat(ln("a"), ln("b"), bytes.Repeat([]byte("a"), 50)),
632				limit:    2*l + 50,
633				consumed: 2 * l,
634				first:    []string{"a", "b"},
635				second:   nil,
636				tail:     true,
637			},
638			{
639				name:     "error in the middle of the third line",
640				content:  cat(ln("a"), ln("b"), ln("c")),
641				limit:    2*l + l/2,
642				consumed: 2 * l,
643				first:    []string{"a", "b"},
644				second:   []string{"c"},
645			},
646		}
647		for _, tc := range tests {
648			t.Run(tc.name, func(t *testing.T) {
649				path := filepath.Join(t.TempDir(), "p.jsonl")
650				putFile(t, path, tc.content)
651				p := faultFirstOpen(t, tc.limit)
652	
653				all := newTable()
654				fr1 := step(t, cur(path))
655				fold(all, fr1.part)
656				if !reflect.DeepEqual(partIDs(fr1.part), tc.first) {
657					t.Fatalf("first ids = %v, want %v", partIDs(fr1.part), tc.first)
658				}
659				if !fr1.next.hasIssue || fr1.next.issue != IssueReadError || fr1.next.issueOff != tc.consumed {
660					t.Fatalf("issue = %v at %d (has %v), want IssueReadError at %d",
661						fr1.next.issue, fr1.next.issueOff, fr1.next.hasIssue, tc.consumed)
662				}
663				if fr1.next.offset != tc.consumed {
664					t.Fatalf("offset = %d, want Consumed %d", fr1.next.offset, tc.consumed)
665				}
666	
667				fr2 := step(t, fr1.next)
668				fold(all, fr2.part)
669				if p.opens != 2 {
670					t.Errorf("opens = %d, want 2: the file must be reopened after a read error", p.opens)
671				}
672				if fr2.next.hasIssue {
673					t.Errorf("issue %v still set after a clean read", fr2.next.issue)
674				}
675				if got := partIDs(fr2.part); !reflect.DeepEqual(got, tc.second) {
676					t.Errorf("second ids = %v, want %v (nothing counted twice)", got, tc.second)
677				}
678				if fr2.next.tail != tc.tail {
679					t.Errorf("tail = %v, want %v", fr2.next.tail, tc.tail)
680				}
681				assertMatchesParseSession(t, path, all)
682			})
683		}
684	}
685	
686	// TruncatedFiles is a state too: it follows whether a tail exists right now.
687	func TestReadFileTailFlagFollowsTheFileNow(t *testing.T) {
688		isolateReadFileHome(t)
689		path := filepath.Join(t.TempDir(), "p.jsonl")
690		whole := ln("b")
691		putFile(t, path, cat(ln("a"), whole[:30]))
692		fr1 := step(t, cur(path))
693		if !fr1.next.tail {
694			t.Fatal("tail = false with an incomplete line")
695		}
696		appendFile(t, path, whole[30:])
697		if fr2 := step(t, fr1.next); fr2.next.tail {
698			t.Error("tail still true once the line is complete")
699		}
700	}
701	
702	// --- clock ----------------------------------------------------------------
703	
704	func TestReadFileClampsModTimeToNow(t *testing.T) {
705		isolateReadFileHome(t)
706		path := filepath.Join(t.TempDir(), "p.jsonl")
707		putFile(t, path, ln("a"))
708		now := time.Now().Truncate(time.Second)
709		future := now.Add(time.Hour)
710		if err := os.Chtimes(path, future, future); err != nil {
711			t.Fatal(err)
712		}
713		fr := readFile(cur(path), now)
714		if !fr.next.modTime.Equal(now) {
715			t.Errorf("modTime = %v, want clamped to now %v", fr.next.modTime, now)
716		}
717	
718		past := now.Add(-time.Hour)
719		if err := os.Chtimes(path, past, past); err != nil {
720			t.Fatal(err)
721		}
722		if fr := readFile(cur(path), now); !fr.next.modTime.Equal(past) {
723			t.Errorf("modTime = %v, want the unclamped %v", fr.next.modTime, past)
724		}
725	}
